-- Name: vista_años_disponibles; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public."vista_años_disponibles" AS
 SELECT DISTINCT "año_academico" AS "año"
   FROM ( SELECT alumnos."año_academico"
           FROM public.alumnos
        UNION
         SELECT pagos."año_academico"
           FROM public.pagos
        UNION
         SELECT deudas."año_academico"
           FROM public.deudas) "años"
  ORDER BY "año_academico" DESC;


