--
-- TOC entry 238 (class 1259 OID 16581)
-- Name: vista_resumen_deudas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vista_resumen_deudas AS
 SELECT a.id AS alumno_id,
    a.dni,
    a.nombres,
    a.apellidos,
    g.nombre AS grado,
    g.nivel,
    count(d.id) AS total_deudas,
    COALESCE(sum(d.monto_deuda), (0)::numeric) AS total_deuda,
    count(
        CASE
            WHEN tp.es_matricula THEN 1
            ELSE NULL::integer
        END) AS matricula_deuda,
    count(
        CASE
            WHEN tp.es_pension THEN 1
            ELSE NULL::integer
        END) AS pensiones_deuda
   FROM (((public.alumnos a
     LEFT JOIN public.grados g ON ((a.grado_id = g.id)))
     LEFT JOIN public.deudas d ON (((a.id = d.alumno_id) AND (d."año_academico" = a."año_academico"))))
     LEFT JOIN public.tipos_pago tp ON ((d.tipo_pago_id = tp.id)))
  WHERE (a.activo = true)
  GROUP BY a.id, a.dni, a.nombres, a.apellidos, g.nombre, g.nivel;


ALTER VIEW public.vista_resumen_deudas OWNER TO postgres;

