--

CREATE VIEW public.vista_resumen_pagos AS
 SELECT a.id AS alumno_id,
    a.dni,
    a.nombres,
    a.apellidos,
    g.nombre AS grado,
    g.nivel,
    count(p.id) AS total_pagos,
    COALESCE(sum(p.monto), (0)::numeric) AS total_pagado,
    count(
        CASE
            WHEN tp.es_matricula THEN 1
            ELSE NULL::integer
        END) AS matricula_pagada,
    count(
        CASE
            WHEN tp.es_pension THEN 1
            ELSE NULL::integer
        END) AS pensiones_pagadas
   FROM (((public.alumnos a
     LEFT JOIN public.grados g ON ((a.grado_id = g.id)))
     LEFT JOIN public.pagos p ON (((a.id = p.alumno_id) AND (p."año_academico" = a."año_academico"))))
     LEFT JOIN public.tipos_pago tp ON ((p.tipo_pago_id = tp.id)))
  WHERE (a.activo = true)
  GROUP BY a.id, a.dni, a.nombres, a.apellidos, g.nombre, g.nivel;


ALTER VIEW public.vista_resumen_pagos OWNER TO postgres;

