--
-- TOC entry 5059 (class 2618 OID 16589)
-- Name: vista_estadisticas_grado _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.vista_estadisticas_grado AS
 SELECT g.id AS grado_id,
    g.codigo,
    g.nombre AS grado,
    g.nivel,
    count(DISTINCT a.id) AS total_alumnos,
    count(DISTINCT p.alumno_id) AS alumnos_con_pagos,
    COALESCE(sum(p.monto), (0)::numeric) AS total_ingresos,
    count(DISTINCT d.alumno_id) AS alumnos_con_deudas,
    COALESCE(sum(d.monto_deuda), (0)::numeric) AS total_deudas
   FROM (((public.grados g
     LEFT JOIN public.alumnos a ON (((g.id = a.grado_id) AND (a.activo = true))))
     LEFT JOIN public.pagos p ON (((a.id = p.alumno_id) AND (p."año_academico" = a."año_academico"))))
     LEFT JOIN public.deudas d ON (((a.id = d.alumno_id) AND (d."año_academico" = a."año_academico"))))
  GROUP BY g.id, g.codigo, g.nombre, g.nivel
  ORDER BY g.orden;


